# Generated by scripts/wasm/prepare_gateway_finalizer.py.
# Verbatim source except two explicit transport rewrites; see provenance.json.
# Candidate is recorded DATA; no authority, Host, generation, or retry.

from __future__ import annotations


from dataclasses import dataclass


from typing import Any, Iterable, Mapping


class GlobalContractInvocationError(RuntimeError):
    """Preserve a provider-neutral operation failure code across isolation."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


_SUCCESS = frozenset({"stop", "end_turn", "completed", "complete"})


_WAIT_USER = frozenset({"waiting_user", "waiting_for_user", "awaiting_user"})


_WAIT_APPROVAL = frozenset(
    {
        "waiting_approval",
        "awaiting_approval",
        "approval_required",
        "authority_approval_required",
    }
)


_RUNNING = frozenset({"running", "streaming", "pending", "tool_call", "tool_calls"})


_CANCELLED = frozenset({"cancelled", "canceled", "interrupted"})


def message_task_state(message: Mapping[str, Any]) -> str:
    """Classify explicit terminal evidence, excluding waiting and idle signals."""
    if message.get("role") == "user":
        return "running"
    if message.get("role") != "assistant":
        return "unknown"
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, Mapping) else {}
    thinking = metadata.get("thinking")
    thinking = thinking if isinstance(thinking, Mapping) else {}
    states = {
        str(message.get("status") or "").lower(),
        str(message.get("finish_reason") or "").lower(),
        str(metadata.get("task_state") or "").lower(),
        str(thinking.get("state") or "").lower(),
    }
    if states & _CANCELLED or metadata.get("cancelled") is True:
        return "cancelled"
    if states & _WAIT_APPROVAL or metadata.get("approval_required") is True:
        return "waiting_approval"
    if states & _WAIT_USER or metadata.get("waiting_for_user") is True:
        return "waiting_user"
    if states & {"error", "failed", "failure"}:
        return "failed"
    if states & _RUNNING or metadata.get("draft") is True or metadata.get("streaming") is True:
        return "running"
    known = _SUCCESS | _WAIT_USER | _WAIT_APPROVAL | _RUNNING | _CANCELLED
    for explicit in (metadata.get("task_state"), thinking.get("state")):
        if explicit not in (None, "") and str(explicit).lower() not in known:
            # Idle, unknown or invalid task state cannot be upgraded by stop.
            return "unknown"
    finish = str(message.get("finish_reason") or "").lower()
    if finish in _SUCCESS and message.get("status") in {
        None,
        "",
        "complete",
        "completed",
        "success",
        "succeeded",
    }:
        return "completed"
    if finish or states & {"error", "failed", "failure"}:
        return "failed"
    return "unknown"


USAGE_CONTRACT = "tobkiri.service.ai.usage.cost.v1"


USAGE_GENERATE_OPERATION = "rumi_ai_usage_pack.ai-usage-cost.generate"


USAGE_STREAM_OPERATION = "rumi_ai_usage_pack.ai-usage-cost.stream"


STREAM_NORMALIZE_CONTRACT = "tobkiri.service.ai.stream.normalize.v1"


STREAM_NORMALIZE_OPERATION = "rumi_ai_stream_pack.ai-stream-normalize"


_PRICING_UNIT_USD_PER_TOKEN = "usd_per_token"


@dataclass(frozen=True)
class Candidate:
    """One catalog model joined to an executable selected provider handle."""

    model_id: str
    provider_instance_id: str
    catalog_provider_instance_id: str
    catalog_revision: str
    capabilities: frozenset[str]
    modalities: frozenset[str]
    context_length: int
    input_cost: float | None
    output_cost: float | None
    priority: int
    available: bool
    health: str
    health_observed_at: float | None
    raw: Mapping[str, Any]


def _finalize_generate_result(
    client: GlobalContractClient,
    value: Any,
    request_id: str,
    attempt_candidate: Candidate,
    attempts: list[dict[str, Any]],
    *,
    streaming: bool,
    packvm_response: bool,
) -> dict[str, Any]:
    """Finalize one provider generation without changing dependency custody."""
    result = _normalize_result(value, request_id, attempt_candidate)
    result["tool_intents"] = _tool_intents(
        client,
        result["tool_intents"],
        request_id,
        streaming=streaming,
    )
    result["usage_cost"] = _usage_cost(
        client,
        result["usage"],
        attempt_candidate,
        result["usage_provenance"],
        streaming=streaming,
    )
    result["attempts"] = attempts
    return _maybe_packvm_safe_response(result, packvm_response)


def _finalize_stream_result(
    client: GlobalContractClient,
    value: Any,
    request_id: str,
    attempt_candidate: Candidate,
    attempt_number: int,
    attempts: list[dict[str, Any]],
    *,
    packvm_response: bool,
) -> dict[str, Any]:
    """Finalize one provider stream in the original usage-before-tools order."""
    normalized = client.invoke(
        STREAM_NORMALIZE_CONTRACT,
        STREAM_NORMALIZE_OPERATION,
        {
            "request_id": request_id,
            "provider_attempt": attempt_number,
            "value": value,
        },
    )
    events = (
        normalized.get("events")
        if isinstance(normalized, Mapping)
        else None
    )
    if not isinstance(events, list):
        raise GlobalContractInvocationError(
            "invalid_response",
            "stream normalizer returned an invalid result",
        )
    _attach_stream_usage_cost(client, events, attempt_candidate)
    _attach_stream_tool_intents(client, events, request_id)
    return _maybe_packvm_safe_response({
        "status": "ok", "output": value.get("output", ""),
        "tool_intents": _tool_intents(
            client, value.get("tool_intents", []), request_id,
            streaming=True,
        ),
        "finish_reason": value.get("finish_reason"),
        "delivery_mode": value.get("delivery_mode", "buffered"),
        "request_id": request_id,
        "model_id": attempt_candidate.model_id,
        "provider_instance_id": attempt_candidate.provider_instance_id,
        "events": events,
        "attempts": attempts,
    }, packvm_response)


def _normalize_result(
    value: Any,
    request_id: str,
    selected: Candidate,
) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise GlobalContractInvocationError(
            "invalid_response",
            "provider result must be an object",
        )
    if value.get("status") not in {None, "ok"}:
        raise GlobalContractInvocationError(
            str(value.get("error_code") or "provider_unavailable"),
            str(value.get("message") or "provider failed"),
        )
    result = {
        "status": "ok",
        "request_id": request_id,
        "model_id": selected.model_id,
        "provider_instance_id": selected.provider_instance_id,
        "catalog_provider_instance_id": (
            selected.catalog_provider_instance_id
        ),
        "catalog_revision": selected.catalog_revision,
        "pricing_revision": selected.catalog_revision,
        "output": value.get("output"),
        "tool_intents": list(value.get("tool_intents") or []),
        "finish_reason": str(value.get("finish_reason") or "stop"),
        "usage": dict(value.get("usage") or {}),
        "usage_provenance": str(
            value.get("usage_provenance") or "provider_reported"
        ),
    }
    metadata = value.get("metadata")
    if "task_state" in value or isinstance(metadata, Mapping):
        # Retain finite terminal evidence from the captured provider result.
        # Arbitrary provider metadata never becomes prompt or authority input.
        evidence = dict(metadata) if isinstance(metadata, Mapping) else {}
        if "task_state" in value:
            evidence["task_state"] = value["task_state"]
        result["task_state"] = message_task_state({
            "role": "assistant", "status": "complete",
            "finish_reason": value.get("finish_reason"), "metadata": evidence,
        })
    return result


def _attach_stream_usage_cost(
    client: GlobalContractClient,
    events: list[dict[str, Any]],
    candidate: Candidate,
) -> None:
    for event in events:
        usage = event.get("usage")
        if event.get("type") == "usage" and isinstance(usage, Mapping):
            event["usage_cost"] = _usage_cost(
                client,
                usage,
                candidate,
                "provider_reported",
                streaming=True,
            )


def _attach_stream_tool_intents(
    client: GlobalContractClient,
    events: list[dict[str, Any]],
    request_id: str,
) -> None:
    for event in events:
        intent = event.get("tool_intent")
        if event.get("type") == "tool_intent_delta" and isinstance(
            intent, Mapping
        ):
            normalized = _tool_intents(
                client,
                [intent],
                request_id,
                streaming=True,
            )
            event["tool_intent"] = normalized[0]


def _usage_cost(
    client: GlobalContractClient,
    usage: Mapping[str, Any],
    candidate: Candidate,
    provenance: str,
    *,
    streaming: bool,
) -> dict[str, Any]:
    return client.invoke(
        USAGE_CONTRACT,
        USAGE_STREAM_OPERATION if streaming else USAGE_GENERATE_OPERATION,
        {
            "usage": dict(usage),
            "usage_provenance": provenance,
            "pricing": {
                "input": candidate.input_cost,
                "output": candidate.output_cost,
                "currency": str(candidate.raw.get("currency") or "USD"),
                "unit": _PRICING_UNIT_USD_PER_TOKEN,
            },
            "pricing_revision": candidate.catalog_revision,
        },
    )


def _tool_intents(
    client: GlobalContractClient,
    intents: list[Any],
    request_id: str,
    *,
    streaming: bool,
) -> list[dict[str, Any]]:
    return client.tool_intents(intents, request_id, streaming=streaming)


def _maybe_packvm_safe_response(
    value: Mapping[str, Any],
    required: bool,
) -> dict[str, Any]:
    """Only ordinary DATA is admitted; Host PackVM transport is absent."""
    if required is not False:
        raise ValueError("Host PackVM serialization is not supported")
    return dict(value)
